<?php
declare(strict_types=1);
require_once __DIR__.'/includes/quality.php';
if (!is_tester()) { header('Location: admin.php'); exit; }
$modules=quality_modules(); $kind=(string)($_GET['module']??''); $module=$modules[$kind]??null; $error=''; $notice=$_SESSION['quality_notice']??''; unset($_SESSION['quality_notice']); $records=[]; $cases=[]; $counts=[]; $edit=null; $data=[]; $files=[];
try {
 quality_schema();
 if ($module && isset($_GET['id'])) { $s=db()->prepare('SELECT * FROM quality_records WHERE id=? AND kind=?'); $s->execute([(int)$_GET['id'],$kind]); $edit=$s->fetch()?:null; if(!$edit) throw new InvalidArgumentException('Registro no encontrado.'); $data=json_decode($edit['payload'],true,512,JSON_THROW_ON_ERROR); }
 if ($module && $_SERVER['REQUEST_METHOD']==='POST') {
  if(!valid_csrf($_POST['csrf_token']??null)) throw new InvalidArgumentException('La sesión del formulario caducó. Recarga la página.');
  foreach(['title','project','responsible','record_date'] as $f) if(!is_string($_POST[$f]??null)||trim($_POST[$f])==='') throw new InvalidArgumentException('Completa los campos obligatorios.');
  if(strlen($_POST['title'])>150 || strlen($_POST['project'])>100 || strlen($_POST['responsible'])>100) throw new InvalidArgumentException('Los datos de identificación son demasiado largos.');
  $date=DateTimeImmutable::createFromFormat('!Y-m-d',$_POST['record_date']); if(!$date||$date->format('Y-m-d')!==$_POST['record_date']) throw new InvalidArgumentException('Fecha no válida.');
  $status=$_POST['status']??''; if(!in_array($status,['Borrador','En revisión','Completado','Abierto','En progreso','Resuelto','Cerrado'],true)) throw new InvalidArgumentException('Estado no válido.');
  $payload=[]; foreach($module[3] as $key=>$label) { if(!is_string($_POST[$key]??'')) throw new InvalidArgumentException('Campo no válido.'); $payload[$key]=trim($_POST[$key]??''); if(mb_strlen($payload[$key])>10000) throw new InvalidArgumentException('El texto supera el límite permitido.'); }
  $rows=$_POST['rows']??[]; if(!is_array($rows)||count($rows)>100) throw new InvalidArgumentException('Se permiten hasta 100 filas.');
  $payload['rows']=[]; foreach($rows as $row) { if(!is_array($row)||count($row)!==count($module[4])) throw new InvalidArgumentException('Fila no válida.'); ksort($row, SORT_NUMERIC); foreach($row as $v) if(!is_string($v)||mb_strlen($v)>2000) throw new InvalidArgumentException('Celda no válida.'); if(implode('', $row)!=='') $payload['rows'][]=array_values($row); }
  if(!$payload['rows']) throw new InvalidArgumentException('Agrega al menos una fila de detalle.');
  if($kind==='boundary') { foreach(['minimum','maximum','step'] as $f) if(!is_numeric($payload[$f])) throw new InvalidArgumentException('Los límites y el incremento deben ser numéricos.'); if((float)$payload['minimum']>(float)$payload['maximum']||(float)$payload['step']<=0) throw new InvalidArgumentException('Revisa el intervalo y utiliza un incremento mayor que cero.'); }
  if($kind==='coverage') { if(!ctype_digit($payload['total'])||!ctype_digit($payload['covered'])||(int)$payload['total']<1||(int)$payload['covered']>(int)$payload['total']) throw new InvalidArgumentException('La cobertura debe tener un total positivo y ejecutados entre cero y el total.'); $payload['score']=round(100*(int)$payload['covered']/(int)$payload['total'],2); }
  if($kind==='rubric') { $weight=0;$score=0; foreach($payload['rows'] as $r) { if(!is_numeric($r[1])||!is_numeric($r[2])||$r[1]<0||$r[1]>100||$r[2]<1||$r[2]>5) throw new InvalidArgumentException('Cada peso debe estar entre 0 y 100 y cada nivel entre 1 y 5.'); $weight+=(float)$r[1];$score+=(float)$r[1]*(float)$r[2]/5; } if(abs($weight-100)>.01) throw new InvalidArgumentException('Los pesos de la rúbrica deben sumar 100 %.'); $payload['score']=round($score,2); }
  if($kind==='assessment') { $sum=0; foreach($payload['rows'] as $r) { if(!is_numeric($r[1])||$r[1]<1||$r[1]>5) throw new InvalidArgumentException('Las puntuaciones deben estar entre 1 y 5.'); $sum+=(float)$r[1]; } $payload['score']=round($sum/count($payload['rows']),2); }
  if($kind==='plan' && (!$payload['start']||!$payload['end']||$payload['end']<$payload['start'])) throw new InvalidArgumentException('Indica el inicio y un fin posterior o igual.');
  if($kind==='incident') foreach(['severity','priority','steps','expected','actual'] as $f) if($payload[$f]==='') throw new InvalidArgumentException('Completa severidad, prioridad, pasos y resultados del incidente.');
  $caseId=filter_var($_POST['case_id']??'',FILTER_VALIDATE_INT)?:null; if($caseId) { $s=db()->prepare('SELECT id FROM test_cases WHERE id=?');$s->execute([$caseId]);if(!$s->fetch()) throw new InvalidArgumentException('El caso relacionado no existe.'); }
  $uploads=quality_uploads(); if($kind==='portfolio'&&!$edit&&!$uploads) throw new InvalidArgumentException('Adjunta al menos un archivo al portafolio.');
  db()->beginTransaction();
  if($edit) { $s=db()->prepare('UPDATE quality_records SET title=?, project=?, responsible=?, record_date=?, status=?, case_id=?, payload=? WHERE id=? AND kind=?');$s->execute([trim($_POST['title']),trim($_POST['project']),trim($_POST['responsible']),$_POST['record_date'],$status,$caseId,json_encode($payload,JSON_UNESCAPED_UNICODE),$edit['id'],$kind]);$id=(int)$edit['id']; }
  else { $s=db()->prepare('INSERT INTO quality_records(kind,title,project,responsible,record_date,status,case_id,payload,created_by) VALUES(?,?,?,?,?,?,?,?,?)'); $s->execute([$kind,trim($_POST['title']),trim($_POST['project']),trim($_POST['responsible']),$_POST['record_date'],$status,$caseId,json_encode($payload,JSON_UNESCAPED_UNICODE),$_SESSION['username']]);$id=(int)db()->lastInsertId(); }
  quality_save_files($uploads,$id,null);db()->commit();$_SESSION['quality_notice']='Registro guardado correctamente.';header('Location: testing.php?module='.urlencode($kind).'&id='.$id);exit;
 }
 $counts=db()->query('SELECT kind,COUNT(*) n FROM quality_records GROUP BY kind')->fetchAll(PDO::FETCH_KEY_PAIR);
 $caseCount=(int)db()->query('SELECT COUNT(*) FROM test_cases')->fetchColumn();
 $cases=db()->query('SELECT id,title FROM test_cases ORDER BY id DESC')->fetchAll();
 if($module) { $s=db()->prepare('SELECT * FROM quality_records WHERE kind=? ORDER BY id DESC LIMIT 50');$s->execute([$kind]);$records=$s->fetchAll(); }
 if($edit) {$s=db()->prepare('SELECT * FROM quality_files WHERE record_id=?');$s->execute([$edit['id']]);$files=$s->fetchAll();}
} catch(Throwable $ex) { try { if(db()->inTransaction())db()->rollBack(); } catch(Throwable $ignored) {} $error=$ex instanceof InvalidArgumentException?$ex->getMessage():'No se pudo completar la operación. Revisa la conexión e inténtalo nuevamente.';error_log($ex->getMessage()); }
function qv(string $key,string $default=''): string { global $edit,$data;return e((string)($_POST[$key]??$edit[$key]??$data[$key]??$default)); }
?>
